mapper.select:


    a.del_flag = '0'

        and a.attendance_no like concat('%', #{attendanceNo}, '%')


        and a.contract_id = #{contractId}


        and a.dispatch_enterprise_id = #{dispatchEnterpriseId}


        and a.person_id = #{personId}


        and a.person_name like concat('%', #{personName}, '%')


        and a.attendance_date >= #{params.beginTime}


        and a.attendance_date < #{params.endTime}


        and a.attendance_status = #{attendanceStatus}


        and a.source_type = #{sourceType}


        and a.collect_status = #{collectStatus}


        and a.att_check = #{attCheck}


        and a.region_code like concat(#{regionCode}, '%')

    ${params.regionDataScope}
    ${params.enterpriseDataScope}

order by a.attendance_date desc, a.attendance_id desc


where a.person_id = #{personId}
  and a.attendance_date = #{attendanceDate}
  and a.del_flag = '0'
order by a.attendance_id desc
limit 1


where a.person_id = #{personId}
  and date_format(a.attendance_date, '%Y-%m') = #{month}
  and a.del_flag = '0'
order by a.attendance_date asc, a.attendance_id asc
